export function useStoredAgentsTreeBranchState(
  key: AgentsTreeExpandStateKey,
  type: AgentBranch,
  id?: AgentBranchId,
  defaultValue = true,
): [boolean, () => void] {
  const expandState = getStoredAgentsTreeExpandState(key)
  const expandStateForType = expandState[type]

  const wasExpanded = expandStateForType != null ? expandStateForType[id!] : false
  const [expanded, setExpanded] = React.useState(
    wasExpanded !== undefined ? wasExpanded : defaultValue,
  )

  const toggleExpanded = React.useCallback(() => {
    if (id != null) {
      setStoredExpandState(key, keyValue(type, keyValue(id, !expanded)))
    }
    setExpanded(!expanded)
  }, [key, type, id, expanded])

  return [expanded, toggleExpanded]
}

export function useSubscribeOnAgentTypes(
  initialQueryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>,
) {
  const [queryReference, loadQuery] = useQueryLoader<AgentsPagesAgentTypesQuery>(
    agentTypesQuery,
    initialQueryRef,
  )

  useEffect(() => {
    let initial = true

    return subscribeOnOverallEvents(REGULAR_OVERALL_AGENT_EVENT_TOPICS, () => {
      if (!initial) {
        loadQuery(
          {
            skipParameters: !isPipelinesAgentPageEnabled(),
          },
          {fetchPolicy: 'store-and-network', networkCacheConfig: {metadata: {isRefetch: true}}},
        )
      }
      initial = false
    })
  }, [loadQuery])

  // workaround for "Expected preloadedQuery to not be disposed yet"
  if (IS_STORYBOOK && queryReference?.isDisposed) {
    throw Promise.resolve()
  }

  return queryReference
}

export function useNativeSubscribeOnAgentTypes(skip: boolean) {
  const [nativeAgentTypesQueryResponse, refetch] = useRefetchableLazyLoadQuery(
    NativeAgentTypesQuery,
    {skip},
  )

  useEffect(() => {
    if (skip) {
      return () => undefined
    }

    let initial = true

    return subscribeOnOverallEvents(REGULAR_OVERALL_AGENT_EVENT_TOPICS, () => {
      if (!initial) {
        refetch()
      }
      initial = false
    })
  }, [refetch, skip])

  if (skip || nativeAgentTypesQueryResponse == null) {
    return undefined
  }

  return getAgentPoolsFromNative({nativeAgentTypesQueryResponse})
}

const agentExistsQuery = graphql`
  query AgentsPagesAgentExistsQuery($locator: String!) {
    agentRest(agentLocator: $locator) {
      id
    }
  }
`
export function useSubscribeOnAgentRemoval(agentId: AgentId, preserveAfterDelete = false) {
  const fetchAgent = useOnDemandQuery<AgentsPagesAgentExistsQuery>(agentExistsQuery)
  const dispatch = useAppDispatch()
  useEffect(
    () =>
      subscribeOnAgentEvents(agentId, [SubscriptionEvents.AGENT_REMOVED], () =>
        fetchAgent({locator: `id:${agentId}`}, true)
          .toPromise()
          .catch(originalError => {
            const error = extractErrorFromRelay(originalError)
            if (
              error != null &&
              'statusCode' in error &&
              error.statusCode === HTTPCodesEnum.NOT_FOUND
            ) {
              dispatch(preserveAfterDelete ? markAgentDeleted(agentId) : removeAgent(agentId))
            }
          }),
      ),
    [agentId, fetchAgent, dispatch, preserveAfterDelete],
  )
}

const limit = 20

export const useRedirectAgentPageUrl = (queryRef: PreloadedQuery<AgentsPagesAgentTypesQuery>) => {
  const agentTypesQueryResponse = usePreloadedQuery(agentTypesQuery, queryRef)
  const favoriteAgentPoolsExist = useAgentPoolFavoriteList().length > 0

  // Clicking on the Agents tab in the header leads to:
  // 1. If there are favorite pools. Display them when opening all agents.
  // 2. If there are no favorite pools and the total number of pools is less than N. Show the Overview.
  // 3. If there are no favorite pools and the total number of pools is more than N. Show the placeholder.
  const poolsCount = agentTypesQueryResponse.agentPoolsRest?.agentPool?.length ?? 0
  return favoriteAgentPoolsExist || poolsCount > limit
    ? getFavoriteAgentPoolsHref()
    : getAgentsOverviewHref()
}

// If there's "view agent details" permission, the API returns the full list of agent pools.
// The same happens if there's "view project agent details" permission, for any project (which apparently is a bug).
// If there are no above permissions, the API returns empty list of agent pools.
// It seems safe to use this fact to detect the lack of permissions.
const canViewAgentDetailsFragment = graphql`
  fragment AgentsPagesCanViewAgentDetailsFragment on Query {
    agentPoolsRest {
      count
    }
  }
`

export function useCanViewAgentDetails(key: AgentsPagesCanViewAgentDetailsFragment$key | null) {
  const {agentPoolsRest} = useFragment(canViewAgentDetailsFragment, key) ?? {}
  return Boolean(agentPoolsRest?.count)
}
