import RingToggle, {Size} from '@jetbrains/ring-ui-built/components/toggle/toggle'

import {getTitle} from '../EnableAgentForm.utils'

type Props = {
  className?: string
  isToggleable: boolean
  isCloud?: boolean
  enabled?: boolean | null
  handleToggleClick: () => unknown
  title?: string
  size?: string
}

function EnableToggle(props: Props) {
  const {
    className,
    enabled,
    isToggleable,
    handleToggleClick,
    title,
    size = Size.Size14,
    isCloud,
  } = props
  return (
    <RingToggle
      title={title == null ? getTitle(enabled, isToggleable, isCloud) : title}
      disabled={!isToggleable}
      checked={enabled === true}
      className={className}
      onChange={handleToggleClick}
      size={size}
    />
  )
}

export default EnableToggle
